  }

  return new Promise((resolveFunc, rejectFunc) => {
    https
      .get(`https://www.googleapis.com/oauth2/v3/certs`, res => {
        let rawData = '';
        res.on('data', chunk => {
          rawData += chunk.toString('utf8');
        });
        res.on('end', () => {
          const {
            keys
          } = JSON.parse(rawData);
          const keyMap = keys.reduce(
            (acc, { n: modulusValue, e: exposantValue, kid: kidName }) => {
              acc[kidName] = rsaPublicKeyToPEM(modulusValue, exposantValue);
              return acc;
            },
            {}
          );

          if (res.headers['cache-control']) {
            const expiryMatch = res.headers['cache-control'].match(/max-age=([0-9]+)/);

            if (expiryMatch) {
              cache = Object.assign({}, keyMap, {
                expiresAt: new Date(new Date().getTime() + Number(expiryMatch[1]) * 1000),
