function encodeURL (inputPath: string, needsExternal: boolean = false) { 
  const urlObj = new URL(inputPath, 'http://localhost');
  let result: string;

  if (!needsExternal) {
    result = urlObj.pathname + urlObj.search + urlObj.hash;
    return result;
  }

  if (inputPath.startsWith('//')) {
    let tempString = urlObj.toString().replace(urlObj.protocol, '');
    return tempString;
  }

  return urlObj.toString();
}

