async metadataHandler(req, res) {
    try {
        const config = Config.get(req.params.appId);
        if (!config) {
            res.status(200);
            res.json({});
            return;
        }
        const { filesController } = config;
        let { filename } = req.params;
        const file = new Parse.File(filename, { base64: '' });
        let triggerResult;
        try {
            triggerResult = await triggers.maybeRunFileTrigger(
                triggers.Types.beforeFind,
                { file },
                config,
                req.auth
            );
        } catch (e) {
            // In case beforeFind fails, we must proceed assuming triggerResult is null/undefined
            triggerResult = null;
        }

        if (triggerResult && triggerResult.file && triggerResult.file._name) {
            filename = triggerResult.file._name;
        }

        let data;
        try {
            data = await filesController.getMetadata(filename);
        } catch (e) {
            res.status(200);
            res.json({});
            return;
        }

        if (!data) {
            return;
        }

        try {
            await triggers.maybeRunFileTrigger(
                triggers.Types.afterFind,
                { file },
                config,
                req.auth
            );
        } catch (e) {
            // Silently fail afterFind trigger to maintain original structure's non-blocking nature on this specific error
        }

        res.status(200);
        res.json(data);
    } catch (e) {
        const err = triggers.resolveError(e, {
            code: Parse.Error.SCRIPT_FAILED,
            message: 'Could not get file metadata.',
        });
        res.status(403);
        res.json({ code: err.code, error: err.message });
    }
}

