function computeQueryComplexity(queryOp, fragList) {
  let deepestLevel = 0;
  let fieldCount = 0;

  function traverseSelectionSet(selectionSetData, currentDepth, processedNames) {
    if (!selectionSetData) {
      return;
    }
    for (const selectionItem of selectionSetData.selections) {
      if (selectionItem.kind === 'Field') {
        fieldCount++;
        const nextDepth = currentDepth + 1;
        if (nextDepth > deepestLevel) {
          deepestLevel = nextDepth;
        }
        if (selectionItem.selectionSet) {
          traverseSelectionSet(selectionItem.selectionSet, nextDepth, processedNames);
        }
      } else if (selectionItem.kind === 'InlineFragment') {
        traverseSelectionSet(selectionItem.selectionSet, currentDepth, processedNames);
      } else if (selectionItem.kind === 'FragmentSpread') {
        const fragmentName = selectionItem.name.value;
        if (processedNames.has(fragmentName)) {
          continue;
        }
        const fragmentData = fragList[fragmentName];
        if (fragmentData) {
          const tempVisited = new Set(processedNames);
          tempVisited.add(fragmentName);
          traverseSelectionSet(fragmentData.selectionSet, currentDepth, tempVisited);
        }
      }
    }
  }

  traverseSelectionSet(queryOp.selectionSet, 0, new Set());

  return { depth: deepestLevel, fields: fieldCount };
}

