function calculateQueryComplexity(operationNode, fragmentList) {
  let currentMaxDepth = 0;
  let accumulatedFields = 0;

  function traverseSelectionSet(selectionSet, currentDepth, seenFragments) {
    if (!selectionSet) {
      return;
    }
    for (const selectionItem of selectionSet.selections) {
      if (selectionItem.kind === 'Field') {
        accumulatedFields++;
        const nextDepth = currentDepth + 1;
        if (nextDepth > currentMaxDepth) {
          currentMaxDepth = nextDepth;
        }
        if (selectionItem.selectionSet) {
          traverseSelectionSet(selectionItem.selectionSet, nextDepth, seenFragments);
        }
      } else if (selectionItem.kind === 'InlineFragment') {
        traverseSelectionSet(selectionItem.selectionSet, currentDepth, seenFragments);
      } else if (selectionItem.kind === 'FragmentSpread') {
        const fragmentName = selectionItem.name.value;
        if (seenFragments.has(fragmentName)) {
          continue;
        }
        const fragmentData = fragmentList[fragmentName];
        if (fragmentData) {
          const nextSeen = new Set(seenFragments);
          nextSeen.add(fragmentName);
          traverseSelectionSet(fragmentData.selectionSet, currentDepth, nextSeen);
        }
      }
    }
  }

  traverseSelectionSet(operationNode.selectionSet, 0, new Set());

  return { depth: currentMaxDepth, fields: accumulatedFields };
}

