  } else if (typeof arg === 'object' && arg !== null && 'path' in arg) {
    path = arg.path;
  } else {
    // This branch handles H3Event or other objects that might not fit the explicit checks but were passed.
    // Given the original logic, if it's not string, we assume it has a path property if it's an object type matching the structure.
    // For H3Event compatibility, we rely on the structure that leads to path being set correctly.
    // Replicating the original behavior: if not string, use arg.path.
    path = (arg as any).path;
  }

  try {
    return routeRulesMatcher(path);
  } catch (e) {
    console.error('[nuxt] Error matching route rules.', e);
    return {};
  }
}

