async (context) => {
            const userSession = context.context.session;
            const orgAdapter = getOrgAdapter<O>(context.context, options);
            const inviteRecord = await orgAdapter.findInvitationById(
                context.body.invitationId,
            );

            if (
                !inviteRecord ||
                inviteRecord.expiresAt < new Date() ||
                inviteRecord.status !== "pending"
            ) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.INVITATION_NOT_FOUND,
                );
            }

            // TODO(#9124): `session.user.email` becomes nullable in v2 — this
            // comparison and its mirrors in rejectInvitation, getInvitation, and
            // listUserInvitations need null handling.
            if (inviteRecord.email.toLowerCase() !== userSession.user.email.toLowerCase()) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.YOU_ARE_NOT_THE_RECIPIENT_OF_THE_INVITATION,
                );
            }

            if (
                context.context.orgOptions.requireEmailVerificationOnInvitation &&
                !userSession.user.emailVerified
            ) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.EMAIL_VERIFICATION_REQUIRED_BEFORE_ACCEPTING_OR_REJECTING_INVITATION,
                );
            }

            const membershipCap = context.context.orgOptions?.membershipLimit || 100;
            const memberCount = await orgAdapter.countMembers({
                organizationId: inviteRecord.organizationId,
            });

            const orgEntity = await orgAdapter.findOrganizationById(
                inviteRecord.organizationId,
            );
            if (!orgEntity) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.ORGANIZATION_NOT_FOUND,
                );
            }

            let limitValue = typeof membershipCap === "number"
                ? membershipCap
                : await membershipCap(userSession.user, orgEntity);

            if (memberCount >= limitValue) {
                throw APIError.from(
                    "FORBIDDEN",
                    ORGANIZATION_ERROR_CODES.ORGANIZATION_MEMBERSHIP_LIMIT_REACHED,
                );
            }

            // Run beforeAcceptInvitation hook
            if (options?.organizationHooks?.beforeAcceptInvitation) {
                await options?.organizationHooks.beforeAcceptInvitation({
                    invitation: inviteRecord as unknown as Invitation,
                    user: userSession.user,
                    organization: orgEntity,
                });
            }

            const acceptedInvitationData = await orgAdapter.updateInvitation({
                invitationId: context.body.invitationId,
                status: "accepted",
            });
            if (!acceptedInvitationData) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.FAILED_TO_RETRIEVE_INVITATION,
                );
            }

            let teamIdsArray: string[] = [];
            if (
                context.context.orgOptions.teams &&
                context.context.orgOptions.teams.enabled &&
                "teamId" in acceptedInvitationData &&
                acceptedInvitationData.teamId
            ) {
                teamIdsArray = (acceptedInvitationData.teamId as string).split(",");
                const singleTeam = teamIdsArray.length === 1;

                for (const tId of teamIdsArray) {
                    await orgAdapter.findOrCreateTeamMember({
                        teamId: tId,
                        userId: userSession.user.id,
                    });

                    if (
                        typeof context.context.orgOptions.teams.maximumMembersPerTeam !==
                        "undefined"
                    ) {
                        const currentMembers = await orgAdapter.countTeamMembers({ teamId: tId });

                        const maxMembers = 
                            typeof context.context.orgOptions.teams.maximumMembersPerTeam ===
                            "function"
                                ? await context.context.orgOptions.teams.maximumMembersPerTeam({
                                        teamId: tId,
                                        session: userSession,
                                        organizationId: inviteRecord.organizationId,
                                    })
                                : context.context.orgOptions.teams.maximumMembersPerTeam;

                        if (currentMembers >= maxMembers) {
                            throw APIError.from(
                                "FORBIDDEN",
                                ORGANIZATION_ERROR_CODES.TEAM_MEMBER_LIMIT_REACHED,
                            );
                        }
                    }
                }

                if (singleTeam) {
                    const teamIdToActivate = teamIdsArray[0]!;
                    const updatedSessionState = await orgAdapter.setActiveTeam(
                        userSession.session.token,
                        teamIdToActivate,
                        context,
                    );

                    await setSessionCookie(context, {
                        session: updatedSessionState,
                        user: userSession.user,
                    });
                }
            }

            const newMember = await orgAdapter.createMember({
                organizationId: inviteRecord.organizationId,
                userId: userSession.user.id,
                role: inviteRecord.role,
                createdAt: new Date(),
            });

            await orgAdapter.setActiveOrganization(
                userSession.session.token,
                inviteRecord.organizationId,
                context,
            );
            if (options?.organizationHooks?.afterAcceptInvitation) {
                await options?.organizationHooks.afterAcceptInvitation({
                    invitation: acceptedInvitationData as unknown as Invitation,
                    member: newMember,
                    user: userSession.user,
                    organization: orgEntity,
                });
            }
            return context.json({
                invitation: acceptedInvitationData,
                member: newMember,
            });
        }

