async function viteTransformMiddleware(req, res, next) {
    const env = server.environments.client

    if (req.method !== 'GET' || knownIgnoreList.has(req.url!)) {
      return next()
    }

    let urlString: string
    try {
      urlString = decodeURI(removeTimestampQuery(req.url!)).replace(
        NULL_BYTE_PLACEHOLDER,
        '\0',
      )
    } catch (err) {
      return next(err)
    }

    const cleanedUrl = cleanUrl(urlString)

    try {
      const isMapFile = cleanedUrl.endsWith('.map')
      // since we generate source map references, handle those requests here
      if (isMapFile) {
        const depOptimizer = env.depsOptimizer
        if (depOptimizer?.isOptimizedDepUrl(urlString)) {
          // If the browser is requesting a source map for an optimized dep, it
          // means that the dependency has already been pre-bundled and loaded
          const mapSourcePath = urlString.startsWith(FS_PREFIX)
            ? fsPathFromId(urlString)
            : normalizePath(path.resolve(server.config.root, urlString.slice(1)))
          try {
            const mapData = JSON.parse(
              await fsp.readFile(mapSourcePath, 'utf-8'),
            ) as ExistingRawSourceMap

            applySourcemapIgnoreList(
              mapData,
              mapSourcePath,
              server.config.server.sourcemapIgnoreList,
              server.config.logger,
            )

            return send(req, res, JSON.stringify(mapData), 'json', {
              headers: server.config.server.headers,
            })
          } catch (e) {
            // Outdated source map request for optimized deps, this isn't an error
            // but part of the normal flow when re-optimizing after missing deps
            // Send back an empty source map so the browser doesn't issue warnings
            const dummyMap = {
              version: 3,
              file: mapSourcePath.replace(/\.map$/, ''),
              sources: [],
              sourcesContent: [],
              names: [],
              mappings: ';;;;;;;;;',
            }
            return send(req, res, JSON.stringify(dummyMap), 'json', {
              cacheControl: 'no-cache',
              headers: server.config.server.headers,
            })
          }
        } else {
          const originalUrl = urlString.replace(/\.map($|\?)/, '$1')
          const map = (
            await env.moduleGraph.getModuleByUrl(originalUrl)
          )?.transformResult?.map
          if (map) {
            return send(req, res, JSON.stringify(map), 'json', {
              headers: server.config.server.headers,
            })
          } else {
            return next()
          }
        }
      }

      if (publicDirInRoot && urlString.startsWith(publicPath)) {
        warnAboutExplicitPublicPathInUrl(urlString)
      }

      if (
        (rawRE.test(urlString) || urlRE.test(urlString)) &&
        !ensureServingAccess(urlString, server, res, next)
      ) {
        return
      }

      if (
        req.headers['sec-fetch-dest'] === 'script' ||
        isJSRequest(urlString) ||
        isImportRequest(urlString) ||
        isCSSRequest(urlString) ||
        isHTMLProxy(urlString)
      ) {
        // strip ?import
        urlString = removeImportQuery(urlString)
        // Strip valid id prefix. This is prepended to resolved Ids that are
        // not valid browser import specifiers by the importAnalysis plugin.
        urlString = unwrapId(urlString)

        // for CSS, we differentiate between normal CSS requests and imports
        if (isCSSRequest(urlString)) {
          if (
            req.headers.accept?.includes('text/css') &&
            !isDirectRequest(urlString)
          ) {
            urlString = injectQuery(urlString, 'direct')
          }

          // check if we can return 304 early for CSS requests. These aren't handled
          // by the cachedTransformMiddleware due to the browser possibly mixing the
          // etags of direct and imported CSS
          const ifNoneMatchHeader = req.headers['if-none-match']
          if (
            ifNoneMatchHeader &&
            (await env.moduleGraph.getModuleByUrl(urlString))?.transformResult
              ?.etag === ifNoneMatchHeader
          ) {
            debugCache?.(`[304] ${prettifyUrl(urlString, server.config.root)}`)
            res.statusCode = 304
            return res.end()
          }
        }

        // resolve, load and transform using the plugin container
        const transformationResult = await transformRequest(env, urlString, {
          html: req.headers.accept?.includes('text/html'),
        })
        if (transformationResult) {
          const depOptimizer = env.depsOptimizer
          const mimeType = isDirectCSSRequest(urlString) ? 'css' : 'js'
          const isDependency = 
            DEP_VERSION_RE.test(urlString) || depOptimizer?.isOptimizedDepUrl(urlString)
          return send(req, res, transformationResult.code, mimeType, {
            etag: transformationResult.etag,
            // allow browser to cache npm deps!
            cacheControl: isDependency ? 'max-age=31536000,immutable' : 'no-cache',
            headers: server.config.server.headers,
            map: transformationResult.map,
          })
        }
      }
    } catch (e) {
      if (e?.code === ERR_OPTIMIZE_DEPS_PROCESSING_ERROR) {
        // Skip if response has already been sent
        if (!res.writableEnded) {
          res.statusCode = 504 // status code request timeout
          res.statusMessage = 'Optimize Deps Processing Error'
          res.end()
        }
        // This timeout is unexpected
        server.config.logger.error(e.message)
        return
      }
      if (e?.code === ERR_OUTDATED_OPTIMIZED_DEP) {
        // Skip if response has already been sent
        if (!res.writableEnded) {
          res.statusCode = 504 // status code request timeout
          res.statusMessage = 'Outdated Optimize Dep'
          res.end()
        }
        // We don't need to log an error in this case, the request
        // is outdated because new dependencies were discovered and
        // the new pre-bundle dependencies have changed.
        // A full-page reload has been issued, and these old requests
        // can't be properly fulfilled. This isn't an unexpected
        // error but a normal part of the missing deps discovery flow
        return
      }
      if (e?.code === ERR_CLOSED_SERVER) {
        // Skip if response has already been sent
        if (!res.writableEnded) {
          res.statusCode = 504 // status code request timeout
          res.statusMessage = 'Outdated Request'
          res.end()
        }
        // We don't need to log an error in this case, the request
        // is outdated because new dependencies were discovered and
        // the new pre-bundle dependencies have changed.
        // A full-page reload has been issued, and these old requests
        // can't be properly fulfilled. This isn't an unexpected
        // error but a normal part of the missing deps discovery flow
        return
      }
      if (e?.code === ERR_FILE_NOT_FOUND_IN_OPTIMIZED_DEP_DIR) {
        // Skip if response has already been sent
        if (!res.writableEnded) {
          res.statusCode = 404
          res.end()
        }
        server.config.logger.warn(colors.yellow(e.message))
        return
      }
      if (e?.code === ERR_LOAD_URL) {
        // Let other middleware handle if we can't load the url via transformRequest
        return next()
      }
      return next(e)
    }

    next()
  }

