      request.method !== 'GET' ||
      request.headers.upgrade.toLowerCase() !== 'websocket' ||
      !websocketKey ||
      !keyRegex.test(websocketKey) ||
      (wsVersion !== 8 && wsVersion !== 13) ||
      !this.shouldHandle(request)
    ) {
      return abortHandshake(connection, 400);
    }

    if (this.options.perMessageDeflate) {
      const deflateInstance = new PerMessageDeflate(
        this.options.perMessageDeflate,
